const SB_SITE_REGION_LINKS={"FR": {"FR": "france", "CA": "canada-francais", "BE": "belgique-francais", "CH": "suisse-romande", "LU": "luxembourg-francais", "CI": "cote-divoire"}, "EN": {"GB": "united-kingdom", "US": "united-states", "AU": "australia", "NZ": "new-zealand", "IE": "ireland", "ZA": "south-africa", "SG": "singapore"}, "PT": {"PT": "portugal", "BR": "brasil", "AO": "angola", "MZ": "mocambique"}, "ES": {"ES": "espana", "MX": "mexico", "CO": "colombia", "CL": "chile", "AR": "argentina", "PE": "peru", "EC": "ecuador", "UY": "uruguay", "DO": "republica-dominicana", "US": "hispanohablantes-en-estados-unidos"}, "DE": {"DE": "deutschland"}, "HI": {"IN": "india"}};
function sbUpdateCountries(selected){
 const codes=SB_SITE_COUNTRIES[selected]||[];
 const locale=selected==='UA'?'uk':selected==='EG'?'ar-EG':selected==='ET'?'et':selected.toLowerCase();
 let names;try{names=new Intl.DisplayNames([locale],{type:'region'});}catch(e){names=null;}
 document.getElementById('sbCountryLanguage').textContent=document.querySelector('#siteLangSelect option:checked').textContent.replace(/[\u{1F1E6}-\u{1F1FF}]/gu,'').trim();
 const featured=document.getElementById('sbCountryFeatured'),extra=document.getElementById('sbCountryExtra'),more=document.getElementById('sbCountryMore');
 if(featured.dataset.lang===selected)return;
 featured.dataset.lang=selected;featured.replaceChildren();extra.replaceChildren();more.open=false;more.hidden=codes.length<=4;
 codes.forEach((code,i)=>{
  const slug=SB_SITE_REGION_LINKS[selected]?.[code];const item=document.createElement(slug?'a':'span');item.className='sb-country-pill';
  if(slug)item.href=new URL('country/'+slug+'/',document.baseURI).href;
  const flag=String.fromCodePoint(...[...code].map(c=>127397+c.charCodeAt(0)));
  item.textContent=flag+' '+(names?.of(code)||code);
  (i<4?featured:extra).append(item);
 });
}

(() => {
 const original=setSiteLang;
 function update(lang){
  const selected=(lang||'PL').toUpperCase();const t=SB_DESIGN_COPY[selected]||SB_DESIGN_COPY.EN;
  document.querySelectorAll('[data-copy]').forEach(el=>{el.textContent=t[el.dataset.copy]||SB_DESIGN_COPY.EN[el.dataset.copy]||'';});
  sbUpdateCountries(selected);
  document.getElementById('heroMeaning').textContent=t.letterSummary;
  const isGerman=selected==='DE';document.getElementById('heroPair').textContent=(isGerman?'EN':'DE')+' → '+selected;
  const src=document.getElementById('heroSource');src.lang=isGerman?'en':'de';src.textContent=isGerman?'Please provide proof of your address and the completed form within 14 days of receiving this letter.':'Bitte reichen Sie einen Nachweis Ihrer Anschrift und das ausgefüllte Formular innerhalb von 14 Tagen nach Erhalt dieses Schreibens nach.';
  document.querySelectorAll('.group').forEach(group=>{group.querySelector('.expandhint').textContent=group.open?t.collapse:t.expand;});
  document.querySelectorAll('[data-app-example]').forEach(img=>{
   const url=new URL('assets/app-examples/'+selected+'-'+img.dataset.appExample+'.webp',document.baseURI);url.searchParams.set('v','20261007-2');
   if(img.src!==url.href){img.style.visibility='hidden';img.onload=()=>{img.style.visibility='';};img.onerror=()=>{img.style.visibility='';};img.src=url.href;}
  });
  document.querySelectorAll('[data-app-example]').forEach(img=>{const heading=img.closest('.story')?.querySelector('h3');if(heading)img.alt=heading.textContent;img.setAttribute('aria-label',t.zoom+' · '+img.alt);});
  document.querySelectorAll('.zoom-link').forEach(btn=>btn.textContent=t.zoom);
  document.querySelectorAll('a.app-cta').forEach(a=>{const u=new URL(a.href);u.searchParams.set('lang',selected);if(a.closest('#add-to-phone'))u.searchParams.set('install','1');a.href=u.href;});
 }
 setSiteLang=function(lang){original(lang);update(lang);};
 document.querySelectorAll('.group').forEach(group=>group.addEventListener('toggle',()=>update(document.getElementById('siteLangSelect').value)));
 const nav=document.querySelector('.sb-nav-toggle'),links=document.getElementById('sbNavLinks');if(nav&&links){nav.hidden=false;nav.addEventListener('click',()=>{const open=links.classList.toggle('sb-nav-open');nav.setAttribute('aria-expanded',String(open));});}
 let dialog,trigger;
 function zoom(img){trigger=img;if(!dialog){dialog=document.createElement('dialog');dialog.className='sb-example-zoom';document.body.append(dialog);dialog.addEventListener('close',()=>trigger?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}dialog.replaceChildren();const close=document.createElement('button');close.type='button';close.className='sb-example-zoom-close';close.textContent='×';const lang=document.getElementById('siteLangSelect').value;close.setAttribute('aria-label',SB_PAGE_I18N[lang]?.['Zamknij']||'Close');close.addEventListener('click',()=>dialog.close());const big=document.createElement('img');big.src=img.src;big.alt=img.alt;dialog.append(close,big);dialog.showModal();}
 document.querySelectorAll('[data-zoom]').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.addEventListener('click',()=>zoom(img));img.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();zoom(img);}});const button=document.createElement('button');button.type='button';button.className='zoom-link';button.addEventListener('click',()=>zoom(img));img.insertAdjacentElement('afterend',button);});
 document.getElementById('siteLangSelect').addEventListener('change',()=>{if(dialog?.open)dialog.close();});
 update(document.getElementById('siteLangSelect').value);
})();
